 "content": "def transform(grid):
    # Source shape is a closed path; output is that path in scan order,
    # with the top and bottom spans retained and side edges unrolled.
    h, w = len(grid), len(grid[0])
    pts = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    if not pts:
        return [row[:] for row in grid]
    top = min(r for r, c, v in pts)
    bottom = max(r for r, c, v in pts)
    left = min(c for r, c, v in pts)
    right = max(c for r, c, v in pts)
    out = [[0] * w for _ in range(h)]
    # Top/bottom edges transform to top/bottom spans. Side boundary pixels
    # form diagonals stepping one column right as the row descends.
    for r, c, v in pts:
        if r == top:
            nc = c - left
        elif r == bottom:
            nc = c - left
        elif c == left:
            nc = r - top - 1
        elif c == right:
            nc = r - top + 1
        else:
            continue
        if 0 <= nc < w:
            out[r][nc] = v
    return out
